package dev.zomboid.npcprobe;
import java.util.*;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.entity.ai.attributes.AttributeModifier;
public class Checks{
 static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}static void eq(double a,double b,String s){check(Math.abs(a-b)<.0001,s+" "+a);}
 public static class Tag{public Map<String,Object> values=new HashMap<>();public boolean getBoolean(String k){return Boolean.TRUE.equals(values.get(k));}public void putBoolean(String k,boolean v){values.put(k,v);}public double getDouble(String k){return ((Number)values.getOrDefault(k,0.)).doubleValue();}public void putDouble(String k,double v){values.put(k,v);}public long getLong(String k){return ((Number)values.getOrDefault(k,0L)).longValue();}public void putLong(String k,long v){values.put(k,v);}public int getInt(String k){return ((Number)values.getOrDefault(k,0)).intValue();}public void putInt(String k,int v){values.put(k,v);}public String getString(String k){return String.valueOf(values.getOrDefault(k,""));}public void putString(String k,String v){values.put(k,v);}public void remove(String k){values.remove(k);}}
 public static class Vec{public double x,y,z;public Vec(double x,double y,double z){this.x=x;this.y=y;this.z=z;}public Vec add(Vec v){return new Vec(x+v.x,y+v.y,z+v.z);}public Vec scale(double v){return new Vec(x*v,y*v,z*v);}}
 public static class Box{public Vec hit=new Vec(0,1,0);public Optional<Vec> clip(Vec start,Vec end){return Optional.ofNullable(hit);}}
 public static class Attr{public Map<ResourceLocation,AttributeModifier> values=new HashMap<>();public AttributeModifier getModifier(ResourceLocation id){return values.get(id);}public void removeModifier(ResourceLocation id){values.remove(id);}public void addTransientModifier(AttributeModifier m){values.put(m.id(),m);}}
 public static class Nav{public int stops;public void stop(){stops++;}}
 public static class World{public long time=100;public Map<UUID,Actor> players=new HashMap<>();public long getGameTime(){return time;}public boolean isClientSide(){return false;}public Actor getPlayerByUUID(UUID id){return players.get(id);}}
 public static class Stack{public String item;public int count;public Stack(String id,int n){item=id;count=n;}public boolean isEmpty(){return count<=0;}public Object getItem(){return this;}public void shrink(int n){count=Math.max(0,count-n);}public String toString(){return item;}}
 public static class Ability{public boolean instabuild;}
 public static class Actor extends net.minecraft.world.entity.player.Player{public UUID uuid=UUID.randomUUID();public World world;public double distance=1;public boolean alive=true;public int hurtTime;public String message;public Stack held=new Stack("minecraft:air",0);public Ability ability=new Ability();public Stack getItemInHand(Object hand){return held;}public Ability getAbilities(){return ability;}public Vec getEyePosition(){return new Vec(0,1.6,-3);}public Vec getViewVector(float f){return new Vec(0,0,1);}public UUID getUUID(){return uuid;}public double distanceToSqr(Object npc){return distance;}public boolean isAlive(){return alive;}public void displayClientMessage(Component text,boolean bar){message=text.text();}}
 public static class Entity extends mod.cdv.tnpc.entity.AutoGunOperator{
  public Tag tag=new Tag();public World world=new World();public float health=20;public int died,aimCalls,reloadCalls;public Object target,pose;public Nav nav=new Nav();public Box box=new Box();public Map<Object,Attr> attributes=new HashMap<>();public Component name;
  public Entity(){tag.putBoolean("np15_test",true);tag.putString("np15_mode","quieto");Parts.init(this,null);}
  public Tag getPersistentData(){return tag;}public Object getEntityData(){return new Skin();}public World level(){return world;}public double getX(){return 0;}public double getY(){return 0;}public double getZ(){return 0;}public float getYRot(){return 0;}public float getBbHeight(){return 1.85f;}public float getMaxHealth(){return 20;}public void setHealth(float h){health=h;}public boolean isAlive(){return health>0&&died==0;}public Object getAttribute(Object key){return attributes.computeIfAbsent(key,k->new Attr());}public void setPose(Object p){pose=p;}public void setCustomName(Component n){name=n;}public void setCustomNameVisible(boolean b){}public void cancelReload(){reloadCalls++;}public void aim(boolean b){aimCalls++;}public void setTarget(Object t){target=t;}public Nav getNavigation(){return nav;}public Box getBoundingBox(){return box;}public Object damageSources(){return new Sources();}public void die(Source s){died++;}public void setNoAi(boolean b){}
 }
 public static class Skin{public Tag get(Object key){return new Tag();}}
 public static class Bullet{public Vec hit;public Bullet(Vec hit){this.hit=hit;}public Vec position(){return hit;}}
 public static class Source{public String id="arrow";public Object attacker,direct;public String getMsgId(){return id;}public Object getEntity(){return attacker;}public Object getDirectEntity(){return direct;}}
 public static class Sources{public Source genericKill(){Source s=new Source();s.id="genericKill";return s;}}
 public static class Event{Entity entity;Source source;float damage;public Event(Entity n,Source s,float a){entity=n;source=s;damage=a;}public Entity getEntity(){return entity;}public Source getSource(){return source;}public float getNewDamage(){return damage;}}
 public static void main(String[]args){
  check(Parts.KEYS.length==8&&Parts.DEFAULT.length==8,"eight named parts");double[] healthy=Parts.DEFAULT.clone();check(!Parts.critical(healthy),"healthy not critical");
  eq(Parts.zone(.95,0),0,"head zone");eq(Parts.zone(.7,0),1,"torso zone");eq(Parts.zone(.7,.3),2,"left arm in NPC coordinates");eq(Parts.zone(.7,-.3),3,"right arm");eq(Parts.zone(.3,.2),4,"left leg");eq(Parts.zone(.3,-.2),5,"right leg");eq(Parts.zone(.08,.2),6,"left foot");eq(Parts.zone(.08,-.2),7,"right foot");
  for(int part=0;part<8;part++){double[] hit=Parts.damaged(healthy,part,100);eq(hit[part],0,"part can be destroyed");check(Parts.critical(hit)==(part<2),"only head/torso critical");for(int i=0;i<8;i++)if(i!=part)eq(hit[i],healthy[i],"other part unaffected");}
  double[] broken=Parts.damaged(healthy,2,100);eq(Parts.strength(broken),.65,"arm damage weakens melee");broken=Parts.damaged(broken,3,100);eq(Parts.strength(broken),.25,"both arms worse");broken=Parts.damaged(healthy,4,100);eq(Parts.speed(broken),.6,"leg slowdown");broken=Parts.damaged(broken,5,100);eq(Parts.speed(broken),.25,"two legs slowdown");
  Entity npc=new Entity();Actor owner=new Actor();owner.world=npc.world;npc.world.players.put(owner.uuid,owner);npc.tag.putString("np15_owner",owner.uuid.toString());Source source=new Source();source.attacker=owner;source.direct=owner;
  npc.box.hit=new Vec(.3,1.2,0);Parts.post(new Event(npc,source,2));eq(Parts.health(npc)[2],4,"final-damage event damages aimed arm");eq(Parts.health(npc)[1],12,"torso not damaged by arm hit");check(npc.health>0&&!Probe.down(npc),"arm hit stays alive");
  source.direct=new Bullet(new Vec(0,1.75,0));Parts.post(new Event(npc,source,6));check(Probe.down(npc)&&npc.health==1,"head shot collapses without actual death");check(npc.died==0,"collapse has no death/corpse call");check(npc.target==null&&npc.nav.stops>0,"combat halted when down");
  npc.tag.putString("np15_helper",owner.uuid.toString());npc.tag.putLong("np15_revive_start",npc.world.time);npc.world.time+=159;Probe.tick(npc);check(Probe.down(npc),"revive requires full eight seconds");npc.world.time++;Probe.tick(npc);check(!Probe.down(npc),"revives at 160 ticks");eq(Parts.health(npc)[0],1,"critical part restored minimally");eq(Parts.health(npc)[2],4,"arm injury remains after revive");Parts.heal(npc,0,6);eq(Parts.health(npc)[0],6,"bandage healing capped at maximum");
  Parts.apply(npc,1,12);npc.tag.putString("np15_helper",owner.uuid.toString());npc.tag.putLong("np15_revive_start",npc.world.time);owner.distance=10;Probe.tick(npc);check(npc.tag.getString("np15_helper").isEmpty(),"walking away cancels revive");owner.distance=1;
  npc.tag.putString("np15_helper",owner.uuid.toString());owner.hurtTime=1;Probe.tick(npc);check(npc.tag.getString("np15_helper").isEmpty(),"healer hit cancels revive");owner.hurtTime=0;
  Parts.reset(npc);for(int i=0;i<8;i++)eq(Parts.health(npc)[i],Parts.DEFAULT[i],"reset restores every part");check(!Probe.down(npc),"reset clears downed state");
  check(Probe.hurt(npc,source,1)==null,"alive uses normal native armor damage path");Parts.apply(npc,0,6);check(!Probe.hurt(npc,source,1),"first finishing hit blocked");check(npc.died==0,"one hit not final");Probe.hurt(npc,source,1);check(npc.died==0,"two hits not final");Probe.hurt(npc,source,1);check(npc.died==1,"third finisher delegates true death");Probe.finish(npc,source);check(npc.died==1,"final death never duplicated");
  Entity bleed=new Entity();Parts.apply(bleed,1,12);bleed.world.time+=1200;Probe.tick(bleed);check(bleed.died==1,"60 seconds unreanimated causes true death");
  Entity plain=new Entity();plain.tag.putBoolean("np15_test",false);check(!Probe.marked(plain),"normal NPC unmarked");check(Probe.hurt(plain,source,5)==null,"normal NPC damage unaffected");check(!Probe.blockDeath(plain,source),"normal death unaffected");
  Entity torso=new Entity();Parts.apply(torso,0,6);Parts.post(new Event(torso,source,100));eq(Parts.health(torso)[1],12,"downed damage does not corrupt body-part state");check(Parts.summary(torso).contains("brazo_izquierdo"),"all body parts readable");
  Entity medical=new Entity();Actor doctor=new Actor();medical.world.players.put(doctor.uuid,doctor);doctor.world=medical.world;Parts.apply(medical,0,2);medical.box.hit=new Vec(0,1.75,0);doctor.held=new Stack("firstaid:bandage",2);Probe.interact(medical,doctor,new Object());eq(Parts.health(medical)[0],6,"targeted bandage cures aimed head");eq(doctor.held.count,1,"one bandage consumed");Probe.interact(medical,doctor,new Object());eq(doctor.held.count,1,"healthy part does not consume bandage");
  Parts.apply(medical,2,6);medical.box.hit=new Vec(.3,1.2,0);doctor.held=new Stack("firstaid:plaster",1);Probe.interact(medical,doctor,new Object());eq(Parts.health(medical)[2],3,"plaster heals selected arm by three");eq(doctor.held.count,0,"plaster consumed");
  Parts.apply(medical,1,12);doctor.held=new Stack("firstaid:bandage",1);Probe.interact(medical,doctor,new Object());check(medical.tag.getString("np15_helper").isEmpty(),"bandage cannot bypass revival");eq(doctor.held.count,1,"downed patient does not eat bandage");doctor.held=new Stack("minecraft:air",0);Probe.interact(medical,doctor,new Object());check(medical.tag.getString("np15_helper").equals(doctor.uuid.toString()),"empty hand starts natural revive");medical.world.time+=160;Probe.tick(medical);check(!Probe.down(medical),"natural interaction completes timed revival");
  check(Probe.allied(medical,doctor)==false,"quiet NPC remains a neutral damage target");
  System.out.println("Passed "+checks+" body damage, revival and isolation checks with API doubles; Minecraft runtime untested.");
 }
}
